let XN=0,XH=[],MEM={},mode='in';const E=esc,f1=n=>n.toFixed(1),XP0='<small>Faz um 📶 Ping (clica na origem e depois no destino) e a explicação aparece aqui.</small>';
function enter(){let u='local';try{u=Object.keys(JSON.parse(localStorage.getItem('satnet-users'))||{})[0]||u}catch(e){}
 window.ME=u;KEY='satnet-tracer-v1-'+u;
 if(!load())demo();XH=[];XN=0;try{const d=JSON.parse(localStorage.getItem('satnet-xp-'+u));if(d){XH=d.h;XN=d.n}}catch(e){}
 $('#xl').innerHTML=XH.join('')||XP0}
$('#xpb').onclick=()=>{$('#xl').innerHTML=XH.join('')||XP0;$('#xp').classList.toggle('h')};$('#xx').onclick=()=>$('#xp').classList.add('h');
$('#xcl').onclick=()=>{XH=[];XN=0;$('#xl').innerHTML=XP0;try{localStorage.removeItem('satnet-xp-'+window.ME)}catch(e){}};
function xpShow(){$('#xl').innerHTML=XH.join('');$('#xp').classList.remove('h');$('#xp').scrollTop=0;try{localStorage.setItem('satnet-xp-'+window.ME,JSON.stringify({n:XN,h:XH}))}catch(e){}}
const kindOf=l=>{const s=[get(l.a),get(l.b)];return s.some(n=>n.t=='geo')?['Rádio · satélite GEO']:s.some(n=>n.t=='leo')?['Rádio · satélite LEO']:['Cabo · '+CAB[l.c||'utp'][0]]};
const L3=t=>t=='router'||t=='gs',ROLE={pc:'Host: cria o pacote e recebe a resposta',router:'Router (camada 3): lê o IP de destino, consulta a tabela de rotas, baixa o TTL em 1 e reescreve os MAC',switch:'Switch (camada 2): encaminha pelo MAC, não olha ao IP',gs:'Estação terrestre: faz de gateway e converte cabo ↔ rádio (baixa o TTL)',geo:'Satélite GEO: repetidor rádio no espaço, não altera o IP',leo:'Satélite LEO: repetidor rádio em órbita baixa, não altera o IP',fw:'Firewall: inspeciona e filtra o tráfego, sem alterar o IP',db:'Servidor: recebe o pedido e responde',bk:'Servidor: recebe o pedido e responde',hk:'Host (atacante): origem do tráfego'};
let PI=0;
const card=(t,b)=>`<div class="pc"><h4>${t}</h4><div>${b}</div></div>`,rtt=d=>(4+4*d+3.2).toFixed(1);
const SL=[
['1 · Identificação',()=>`<div class="idn"><div class="idbar"><div class="lgy"><img src="data:image/png;base64," alt="Escola Profissional de Gaia"></div><div class="lgw"><img src="data:image/png;base64," alt="Pessoas 2030 · Portugal 2030 · Cofinanciado pela União Europeia"></div></div><div class="idk">PAP · Prova de Aptidão Profissional</div><h1>Comunicação com Satélites</h1><div class="idl"></div><div class="idc"><div class="idn2">Hugo Leonel Ferreira Augusto</div><div class="idchips"><div class="chip"><small>Curso</small><b>12.º IIGR</b></div><div class="chip"><small>Projeto</small><b>Comunicação com Satélites</b></div></div></div></div>`],
['2 · Objetivo',()=>`<h2>Como comunicam os dispositivos através de IP, na Terra e por satélite?</h2><div class="pg">${card('Problema','As redes por satélite têm latências muito diferentes (GEO contra LEO) e as ferramentas habituais, como o Packet Tracer, não as simulam nem explicam cada passo de um ping.')}${card('Objetivos','• Mostrar como um pacote encontra o destino através do IP<br>• Medir o efeito de cabos, LEO e GEO no RTT<br>• Demonstrar VLAN, firewall e outras defesas<br>• Explicar cada ping passo a passo<br>• Avaliar a voz (VoIP) e controlar IoT pela mesma rede')}${card('Solução','Um simulador de redes (SatNet Tracer) com mapa interativo e um painel que explica cada ping com os IP, as redes e os atrasos reais do cenário.')}</div>`]];
function PR(){$('#pt').innerHTML=SL.map((s,i)=>`<button data-i="${i}" class="${i==PI?'on':''}">${s[0]}</button>`).join('');$('#pb').innerHTML=SL[PI][1]();$('#pi').textContent=`${PI+1} / ${SL.length}`;$('#pp').style.visibility=PI?'':'hidden';$('#pnx').style.visibility=PI<SL.length-1?'':'hidden';
 document.querySelectorAll('#pt [data-i]').forEach(b=>b.onclick=()=>{PI=+b.dataset.i;PR()});
 $('#pr').scrollTop=0}
$('#prb').onclick=()=>{PI=0;$('#pr').style.display='block';PR()};$('#pf').onclick=()=>{const d=document,e=$('#pr');try{d.fullscreenElement?d.exitFullscreen():e.requestFullscreen()}catch(x){}};$('#pq').onclick=()=>$('#pr').style.display='none';
$('#pp').onclick=()=>{PI--;PR()};$('#pnx').onclick=()=>{PI++;PR()};
addEventListener('keydown',e=>{if($('#pr').style.display!='block'||e.target.tagName=='INPUT')return;if(e.key=='ArrowRight'&&PI<SL.length-1){PI++;PR()}else if(e.key=='ArrowLeft'&&PI>0){PI--;PR()}else if(e.key=='Escape')$('#pr').style.display='none'});
Object.assign(ROLE,{ph:'Telemóvel: cliente móvel (Wi-Fi/dados)',pr:'Impressora de rede: recebe trabalhos de impressão',cam:'Câmara IP: envia vídeo para o servidor',ip:'Telefone VoIP: voz sobre IP, normalmente numa VLAN de voz',ac:'Ar condicionado: equipamento de clima controlado pela rede',sn:'Sensor de temperatura: envia leituras periódicas'});
const q=v=>v==null?'NULL':typeof v=='number'?v:"'"+String(v).replace(/'/g,"''")+"'";
$('#sqb').onclick=()=>{$('#squ').textContent=window.ME||'';$('#sqt').value=sqlDump();$('#sq').style.display='flex'};$('#sqx').onclick=()=>$('#sq').style.display='none';$('#sqc').onclick=()=>{$('#sqt').focus();$('#sqt').select()};

// ===== Tabelas de rotas: o ping segue estas tabelas (e não as ligações desenhadas) =====
const isR=n=>!!n&&(n.t=='router'||n.t=='gs'),nbr=(L,c)=>L.map(k=>k.a==c?k.b:k.b==c?k.a:null).filter(o=>o!=null);
const table=R=>[...(R.rt||[]).map(e=>({...e,src:'estática'})),...autoRoutes(R).filter(e=>CFG.autoRt||e.src=='ligada')];
const rtTable=R=>{const H=(R.rt&&R.rt.H)||[];if(!H.length)return'<br><small>Mesma rede: entrega direta (ARP), sem passar por nenhum router.</small><br>';
 return`<table class="xt"><tr><th>Router / estação</th><th>Rota usada</th><th>Next hop</th></tr>${H.map(h=>{const e=h.e;return`<tr><td>${E(h.r.name)}</td><td>${e?E(e.net)+'/'+e.p+' <small>('+e.src+')</small>':'<b style="color:var(--bad)">nenhuma rota</b>'}</td><td>${e?(e.via?E((get(e.via)||{}).name||'?'):'entrega direta'):'—'}</td></tr>`}).join('')}</table>`};
const rtRows=(R,del)=>{const st=(R.rt||[]).map((e,i)=>({...e,src:'estática',i})),au=autoRoutes(R).filter(e=>CFG.autoRt||e.src=='ligada').sort((a,b)=>b.p-a.p||(i2n(a.net)-i2n(b.net)));
 return [...st,...au].map(r=>`<tr><td>${E(r.net)}/${r.p}</td><td>${r.via?E((get(r.via)||{}).name||'?'):'direta'}</td><td>${r.m}</td><td>${r.src}${del&&r.src=='estática'?` <button data-rd="${r.i}" style="padding:0 5px;margin:0">✕</button>`:''}</td></tr>`).join('')};
function rtUI(n){const e=$('#rtb');if(!e)return;if(!isR(n)){e.innerHTML='';return}
 const opt=nodes.filter(x=>isR(x)&&x.id!=n.id).map(x=>`<option value="${x.id}">${E(x.name)}</option>`).join('');
 e.innerHTML=`<h3>🧭 Tabela de rotas</h3><table class="xt"><tr><th>Destino</th><th>Next hop</th><th>Mét.</th><th>Origem</th></tr>${rtRows(n,true)}</table><small style="opacity:.65">Ganha a rota com o prefixo mais longo. Em empate, ganha a menor distância administrativa (ligada 0, estática 1, OSPF 110) e depois o menor custo.</small><div style="display:grid;grid-template-columns:1fr 54px;gap:4px;margin-top:6px"><input id="rn" placeholder="Rede (ex.: 10.2.0.0)"><input id="rp" type="number" min="0" max="32" placeholder="/24"></div><select id="rv" style="margin-top:4px;width:100%"><option value="0">Entrega direta</option>${opt}</select><button id="ra">+ Rota estática</button><span id="rm" style="font-size:11px;color:var(--bad)"></span>`;
 $('#ra').onclick=()=>{const net=$('#rn').value.trim(),pf=+$('#rp').value;if(i2n(net)==null||!(pf>=0&&pf<=32)||$('#rp').value==='')return $('#rm').textContent='Rede ou prefixo inválido.';
  (n.rt=n.rt||[]).push({net,p:pf,via:+$('#rv').value,m:1});log(`🧭 Rota estática em ${E(n.name)}: ${E(net)}/${pf} via ${+$('#rv').value?E(get(+$('#rv').value).name):'entrega direta'}`);rtUI(n)};
 e.querySelectorAll('[data-rd]').forEach(b=>b.onclick=()=>{n.rt.splice(+b.dataset.rd,1);rtUI(n)})}
document.body.insertAdjacentHTML('beforeend','<div id="rtm" style="display:none;position:fixed;inset:0;z-index:60;background:rgba(0,0,0,.6);align-items:center;justify-content:center;padding:16px"><div id="rtw" style="width:min(1000px,100%);max-height:92vh;overflow:auto;background:var(--bg2);color:var(--t);border:1px solid var(--bd);border-radius:16px;padding:16px"></div></div>');
function rtAll(){const R3=nodes.filter(isR);$('#rtw').innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><b style="font-size:18px">🧭 Tabelas de rotas de todos os routers e estações</b><button id="rtx">✕ Fechar</button></div><small style="opacity:.75">Cada linha diz: para chegar a esta rede, envia para este next hop. "Direta" = a rede está ligada a este equipamento. O ping segue estas tabelas.${CFG.autoRt?'':' <b>Rotas automáticas desligadas.</b>'}</small>${R3.length?R3.map(r=>`<h4 style="margin:14px 0 4px;color:var(--sat)">${E(r.name)} <small style="color:var(--t);opacity:.7">${E(r.ip)}/${r.cidr}</small></h4><table class="xt"><tr><th>Destino</th><th>Next hop</th><th>Métrica</th><th>Origem</th></tr>${rtRows(r,false)}</table>`).join(''):'<p>Não há routers nem estações terrestres.</p>'}`;$('#rtm').style.display='flex';$('#rtx').onclick=()=>$('#rtm').style.display='none'}
$('#rtv').onclick=rtAll;$('#rtm').onclick=e=>{if(e.target.id=='rtm')$('#rtm').style.display='none'};
svg.addEventListener('pointerup',()=>setTimeout(()=>{if(fo&&get(fo))rtUI(get(fo))},0));$('#cfg').addEventListener('input',()=>{if(fo&&get(fo))rtUI(get(fo))});
